-- 3) DOĞRULA — kalem toplamı kayıt tutarıyla uyuşuyor mu?
--    (tutar/aylik/kategori_tutar zaten doğru; arayüz kalem eklendiğinde
--     kalemlerden yeniden türetir.)
SELECT ref_no, tutar,
       jsonb_array_length(kalemler) AS kalem_sayisi,
       (SELECT ROUND(SUM((k->>'tutar')::numeric),2)
          FROM jsonb_array_elements(kalemler) k) AS kalem_toplami
  FROM ref_kayitlari WHERE jsonb_array_length(kalemler) > 0
 ORDER BY ref_no;